import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.Ch4PdLd_.js";const k=JSON.parse('{"title":"提示词模板","description":"","frontmatter":{},"headers":[],"relativePath":"customize/prompt-templates.md","filePath":"customize/prompt-templates.md"}'),d={name:"customize/prompt-templates.md"};function n(o,t,l,h,p,r){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="提示词模板" tabindex="-1">提示词模板 <a class="header-anchor" href="#提示词模板" aria-label="Permalink to &quot;提示词模板&quot;">​</a></h1><p>提示词模板把 Markdown 文件变成可复用的 <code>/</code> 命令。当你经常发送相同或相似的提示词，又不需要可执行逻辑或大量配套说明时，用它最合适。</p><h2 id="创建模板" tabindex="-1">创建模板 <a class="header-anchor" href="#创建模板" aria-label="Permalink to &quot;创建模板&quot;">​</a></h2><p>创建 <code>~/.nek/agent/prompts/review.md</code>：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Review staged git changes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">argument-hint: &quot;[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">focus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Review the staged changes (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`git diff --cached\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">). Focus on \${1:-correctness, security, and error handling}.</span></span></code></pre></div><ul><li><strong>文件名就是命令名</strong>，这个模板的命令是 <code>/review</code>。</li><li><code>description</code> 显示在命令补全里；省略时使用第一行非空内容。</li><li><code>argument-hint</code> 可选，提示参数格式：<code>&lt;尖括号&gt;</code> 表示必填，<code>[方括号]</code> 表示可选。</li></ul><p>在会话中新增或修改模板后运行 <code>/reload</code>。</p><h2 id="使用模板" tabindex="-1">使用模板 <a class="header-anchor" href="#使用模板" aria-label="Permalink to &quot;使用模板&quot;">​</a></h2><p>在输入框里输入命令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/review</span></span>
<span class="line"><span>/review concurrency</span></span>
<span class="line"><span>/review &quot;API compatibility&quot;</span></span></code></pre></div><p>nek 在把文本交给模型<strong>之前</strong>展开模板。扩展会先通过 <code>input</code> 事件拿到原始输入；如果有同名的扩展命令，则由扩展命令处理。</p><h2 id="参数替换" tabindex="-1">参数替换 <a class="header-anchor" href="#参数替换" aria-label="Permalink to &quot;参数替换&quot;">​</a></h2><table tabindex="0"><thead><tr><th>写法</th><th>结果</th></tr></thead><tbody><tr><td><code>$1</code>、<code>$2</code>…</td><td>第 N 个参数</td></tr><tr><td><code>$@</code> 或 <code>$ARGUMENTS</code></td><td>全部参数，以空格连接</td></tr><tr><td><code>\${1:-默认值}</code></td><td>第一个参数，没有时用默认值</td></tr><tr><td><code>\${@:-默认值}</code></td><td>全部参数，没有时用默认值</td></tr><tr><td><code>\${@:N}</code></td><td>从第 N 个开始的所有参数</td></tr><tr><td><code>\${@:N:L}</code></td><td>从第 N 个开始的 L 个参数</td></tr></tbody></table><p>参数按类似 shell 的规则拆分，<code>/review &quot;API compatibility&quot;</code> 传入的是一个包含空格的参数。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p><strong>修复失败的测试</strong>（<code>~/.nek/agent/prompts/fix-tests.md</code>）：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Run the tests and fix failures</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">argument-hint: &quot;[test path]&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Run the tests in \${1:-the whole project}. For each failure, find the root cause, fix it, and rerun until the tests pass. Do not change test expectations unless they are wrong; explain any such change.</span></span></code></pre></div><p><strong>写提交信息</strong>（<code>~/.nek/agent/prompts/commit-msg.md</code>）：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Draft a commit message for staged changes</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Read </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`git diff --cached\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> and draft a concise commit message in the format </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`type(scope): summary\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, followed by a short body explaining why. Do not run git commit.</span></span></code></pre></div><h2 id="放在哪里" tabindex="-1">放在哪里 <a class="header-anchor" href="#放在哪里" aria-label="Permalink to &quot;放在哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>作用范围</th></tr></thead><tbody><tr><td><code>~/.nek/agent/prompts/</code></td><td>用户级，所有项目</td></tr><tr><td><code>.nek/prompts/</code></td><td>项目级，信任项目后才加载</td></tr><tr><td>设置 <code>prompts</code></td><td>额外的文件或目录</td></tr><tr><td><code>--prompt-template &lt;路径&gt;</code></td><td>只对本次运行生效（可重复）</td></tr></tbody></table><p>约定目录只加载直接位于其中的 <code>.md</code> 文件（不递归）。通过设置 <code>prompts</code> 可以选中嵌套目录中的 Markdown 文件，并支持 <code>!pattern</code> 排除、<code>+path</code> 精确包含、<code>-path</code> 精确排除，见 <a href="/nekcode/reference/settings#resources">settings.json</a>。</p><p><code>--no-prompt-templates</code>（<code>-np</code>）关闭模板的自动发现和配置加载，显式的 <code>--prompt-template</code> 仍然生效。</p><p>项目模板在信任项目后会成为命令，信任陌生项目前请检查其内容。</p><h2 id="模板、skill-还是扩展" tabindex="-1">模板、Skill 还是扩展？ <a class="header-anchor" href="#模板、skill-还是扩展" aria-label="Permalink to &quot;模板、Skill 还是扩展？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>用</th></tr></thead><tbody><tr><td>一段固定或带参数的提示词</td><td>提示词模板</td></tr><tr><td>一套专项说明，可能附带脚本和参考资料，由模型按需加载</td><td><a href="/nekcode/customize/skills">Skill</a></td></tr><tr><td>需要执行代码、注册工具或修改行为</td><td><a href="/nekcode/develop/extensions">扩展</a></td></tr></tbody></table>`,26)])])}const g=e(d,[["render",n]]);export{k as __pageData,g as default};
